// Google Apps Script Web App: TNHub-Script const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzDummyTNHubScriptDeploymentId/exec";
// Initialize Firebase let app, auth, db; try { app = initializeApp(firebaseConfig); auth = getAuth(app); db = getFirestore(app); } catch (e) { console.warn('Firebase init notice:', e.message); }
const { createApp, ref, computed, onMounted, watch } = Vue;
createApp({ setup() { const activeTab = ref('feed'); const activeCategory = ref('all'); const viewMode = ref('grid'); const searchKeyword = ref(''); const userMenuOpen = ref(false); const showApplyModal = ref(false); const showContactModal = ref(false); const showPostModal = ref(false); const showDetailModal = ref(false); const selectedDetailCard = ref(null); const submittingApply = ref(false); const selectedItem = ref(null);
const currentUser = ref({ displayName: 'Phạm Thanh Quang', email: 'ptquang0968@gmail.com', photoURL: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=120&h=120&q=80' });
const bookmarks = ref(JSON.parse(localStorage.getItem('tnhub_bookmarks') || '["c1"]'));
const toasts = ref([]); const popup = ref({ show: false, title: '', message: '', type: 'info', confirmText: 'Đã hiểu', showCancel: false, cancelText: 'Hủy', onConfirm: null });
const showToast = (message, type = 'info', title = '') => { const id = Date.now() + Math.random(); toasts.value.push({ id, message, type, title }); setTimeout(() => { toasts.value = toasts.value.filter(t => t.id !== id); }, 3500); };
const removeToast = (id) => { toasts.value = toasts.value.filter(t => t.id !== id); };
const showPopup = (title, message, type = 'info', confirmText = 'Đã hiểu', onConfirm = null, showCancel = false) => { popup.value = { show: true, title, message, type, confirmText, showCancel, cancelText: 'Hủy', onConfirm }; };
const handlePopupConfirm = () => { if (popup.value.onConfirm && typeof popup.value.onConfirm === 'function') { popup.value.onConfirm(); } popup.value.show = false; };
