// REALTIME CHAT & NOTIFICATIONS const showChatDrawer = ref(false); const chatMessageInput = ref(''); const unreadMessageCount = ref(0); const communityMessages = ref([ { id: 'msg_1', senderName: 'Phạm Thanh Quang', senderEmail: 'ptquang0968@gmail.com', text: 'Chào mừng quý bà con và đối tác đến với Cổng thông tin & Mạng xã hội TNHub Tây Ninh!', createdAt: new Date(Date.now() - 3600000).toISOString() }, { id: 'msg_2', senderName: 'BQL KCN Trảng Bàng', senderEmail: 'kcn.trangbang@tayninh.gov.vn', text: 'Thông báo: Nhiều doanh nghiệp tại KCN Trảng Bàng đang tuyển dụng hơn 500 vị trí lao động và kỹ thuật viên.', createdAt: new Date(Date.now() - 1800000).toISOString() } ]);
const openChatDrawer = () => { showChatDrawer.value = true; unreadMessageCount.value = 0; };
const playNotificationSound = () => { try { const AudioContext = window.AudioContext || window.webkitAudioContext; if (!AudioContext) return; const ctx = new AudioContext(); const osc = ctx.createOscillator(); const gain = ctx.createGain(); osc.connect(gain); gain.connect(ctx.destination); osc.type = 'sine'; osc.frequency.setValueAtTime(587.33, ctx.currentTime); osc.frequency.setValueAtTime(880, ctx.currentTime + 0.1); gain.gain.setValueAtTime(0.15, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35); osc.start(); osc.stop(ctx.currentTime + 0.35); } catch (e) {} };
const formatTime = (isoString) => { if (!isoString) return 'Vừa xong'; try { const diff = Math.floor((Date.now() - new Date(isoString).getTime()) / 1000); if (diff < 60) return 'Vừa xong'; if (diff < 3600) return Math.floor(diff / 60) + ' phút trước'; if (diff < 86400) return Math.floor(diff / 3600) + ' giờ trước'; return Math.floor(diff / 86400) + ' ngày trước'; } catch (e) { return 'Gần đây'; } };
const sendCommunityMessage = async () => { const text = chatMessageInput.value.trim(); if (!text) return;
const newMsg = { senderName: currentUser.value ? (currentUser.value.displayName || 'Thành viên Google') : 'Thành viên Tây Ninh', senderEmail: currentUser.value ? currentUser.value.email : 'ptquang0968@gmail.com', text: text, createdAt: new Date().toISOString() };
communityMessages.value.unshift({ id: 'msg_' + Date.now(), ...newMsg });
if (db) { try { addDoc(collection(db, 'messages'), newMsg).catch(err => console.warn('Sync message:', err)); } catch (e) { console.warn('Error sending message:', e); } }
chatMessageInput.value = ''; showToast('Đã gửi tin nhắn lên cộng đồng Tây Ninh!', 'success'); };
const selectPin = (pinNum) => { const found = cards.value.find(c => c.pinNumber === pinNum); if (found) { activePinItem.value = { title: found.title, price: found.price, location: found.location, image: found.image }; const queryLocation = encodeURIComponent(found.location + ', Tây Ninh, Việt Nam'); mapEmbedUrl.value = 'https://maps.google.com/maps?q=' + queryLocation + '&t=&z=13&ie=UTF8&iwloc=&output=embed'; showToast('Đang xem vị trí: ' + found.title + ' (' + found.location + ')', 'info'); } };
const selectQuickListItem = (item) => { selectPin(item.number); };
// Lọc thẻ theo Danh mục, Khu vực huyện thị, Tìm kiếm const filteredCards = computed(() => { let list = cards.value;
if (activeCategory.value === 'bookmark') { list = list.filter(c => bookmarks.value.includes(c.id)); } else if (activeCategory.value !== 'all') { list = list.filter(c => c.category === activeCategory.value); }
if (activeDistrict.value !== 'all') { list = list.filter(c => c.district === activeDistrict.value || (c.location && c.location.toLowerCase().includes(activeDistrict.value.toLowerCase()))); }
if (searchKeyword.value.trim() !== '') { const kw = searchKeyword.value.toLowerCase().trim(); list = list.filter(c => (c.title && c.title.toLowerCase().includes(kw)) || (c.subtitle && c.subtitle.toLowerCase().includes(kw)) || (c.location && c.location.toLowerCase().includes(kw)) || (c.description && c.description.toLowerCase().includes(kw)) ); }
if (sortAsc.value) { list = [...list].reverse(); }
return list.slice(0, displayLimit.value); });
const totalFilteredCount = computed(() => { let list = cards.value; if (activeCategory.value === 'bookmark') { list = list.filter(c => bookmarks.value.includes(c.id)); } else if (activeCategory.value !== 'all') { list = list.filter(c => c.category === activeCategory.value); } if (activeDistrict.value !== 'all') { list = list.filter(c => c.district === activeDistrict.value || (c.location && c.location.toLowerCase().includes(activeDistrict.value.toLowerCase()))); } if (searchKeyword.value.trim() !== '') { const kw = searchKeyword.value.toLowerCase().trim(); list = list.filter(c => (c.title && c.title.toLowerCase().includes(kw)) || (c.subtitle && c.subtitle.toLowerCase().includes(kw)) || (c.location && c.location.toLowerCase().includes(kw)) || (c.description && c.description.toLowerCase().includes(kw)) ); } return list.length; });
const hasMoreCards = computed(() => { return displayLimit.value < totalFilteredCount.value; });
const remainingCardsCount = computed(() => { const diff = totalFilteredCount.value - displayLimit.value; return diff > 0 ? diff : 0; });
const loadMore = () => { displayLimit.value += 12; showToast('Đang hiển thị thêm 12 tin đăng tiếp theo...', 'info'); };
const setCategory = (cat) => { activeCategory.value = cat; activeTab.value = 'feed'; displayLimit.value = 12; showToast('Đã lọc theo: ' + cat, 'info'); };
const filterBookmarks = () => { activeCategory.value = 'bookmark'; activeTab.value = 'feed'; displayLimit.value = 12; showToast('Đang hiển thị các tin đã lưu của bạn (' + bookmarks.value.length + ' tin)', 'info'); };
const isBookmarked = (id) => bookmarks.value.includes(id);
const toggleBookmark = (card) => { const index = bookmarks.value.indexOf(card.id); if (index > -1) { bookmarks.value.splice(index, 1); showToast('Đã bỏ lưu tin: ' + card.title, 'info'); } else { bookmarks.value.push(card.id); showToast('Đã lưu tin vào bộ sưu tập cá nhân!', 'success'); } localStorage.setItem('tnhub_bookmarks', JSON.stringify(bookmarks.value)); };
const toggleSort = () => { sortAsc.value = !sortAsc.value; showToast('Đã đổi thứ tự hiển thị tin đăng', 'info'); };
const zoomMap = () => { showToast('Đang mở rộng tầm quan sát bản đồ Tây Ninh', 'info'); };
const onSearchKey = () => { displayLimit.value = 12; };
// Form handlers const applyForm = ref({ fullName: '', phone: '', email: '', note: '', fileBase64: null }); const contactForm = ref({ name: '', phone: '', message: '' }); const postForm = ref({ title: '', category: 'tuyendung', district: 'tptayninh', location: 'TP. Tây Ninh', address: '', price: '', subprice: '', badge: 'Tuyển gấp', description: '', contactName: '', contactPhone: '0908.123.456', imageBase64: null, previewUrl: '' });
const getCategoryLabel = (category) => { const map = { 'tuyendung': 'Tuyển dụng', 'batdongsan': 'Bất động sản', 'raovat': 'Mua bán - Rao vặt', 'suachua': 'Dịch vụ - Thợ', 'amthuc': 'Ẩm thực - Khách sạn' }; return map[category] || 'Tin đăng'; };
const getDistrictName = (districtKey) => { const map = { 'tptayninh': 'TP. Tây Ninh', 'trangbang': 'TX. Trảng Bàng', 'hoathanh': 'TX. Hòa Thành', 'godau': 'Huyện Gò Dầu', 'bencau': 'Huyện Bến Cầu', 'duongminhchau': 'Huyện Dương Minh Châu', 'tanchau': 'Huyện Tân Châu', 'tanbien': 'Huyện Tân Biên', 'chauthanh': 'Huyện Châu Thành' }; return map[districtKey] || 'Tây Ninh'; };
const getCardDescription = (card) => { if (!card) return ''; if (card.description && card.description.trim()) { return card.description; } const title = card.title || ''; const subtitle = card.subtitle || ''; const price = card.price || ''; const subprice = card.subprice || ''; const location = card.location || 'Tây Ninh';
if (card.category === 'tuyendung') { return "THÔNG TIN TUYỂN DỤNG CHI TIẾT:\n" + "• Vị trí: " + title + "\n" + "• Đơn vị tuyển dụng: " + (subtitle || 'Doanh nghiệp tại Tây Ninh') + "\n" + "• Mức thu nhập: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" + "• Khu vực làm việc: " + location + "\n\n" + "MÔ TẢ CÔNG VIỆC:\n" + "- Phụ trách các công việc chuyên môn theo sự phân công của quản lý bộ phận.\n" + "- Phối hợp làm việc cùng đội ngũ nhằm đạt mục tiêu kinh doanh và chất lượng công việc.\n\n" + "YÊU CẦU ỨNG VIÊN:\n" + "- Nhanh nhẹn, trung thực, có tinh thần trách nhiệm cao trong công việc.\n" + "- Ưu tiên ứng viên cư trú tại Tây Ninh hoặc các khu vực lân cận.\n\n" + "QUYỀN LỢI ĐƯỢC HƯỞNG:\n" + "- Lương thưởng minh bạch, đóng BHXH, BHYT đầy đủ theo quy định của pháp luật.\n" + "- Nghỉ lễ tết, thưởng tháng 13 và du lịch hàng năm cùng công ty."; } else if (card.category === 'batdongsan') { return "THÔNG TIN BẤT ĐỘNG SẢN CHI TIẾT:\n" + "• Tiêu đề: " + title + "\n" + "• Vị trí: " + (subtitle || location) + "\n" + "• Giá bán: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" + "• Khu vực: " + location + "\n\n" + "THÔNG TIN QUY HOẠCH & TIỀM NĂNG:\n" + "- Pháp lý chuẩn, sổ hồng riêng chính chủ, công chứng sang tên ngay trong ngày.\n" + "- Đường trước nhà thông thoáng, ô tô ra vào thoải mái, gần khu dân cư đông đúc.\n" + "- Bán kính 1km đầy đủ tiện ích: chợ, trường học, trạm y tế, ủy ban nhân dân.\n" + "- Phù hợp xây nhà định cư lâu dài hoặc đầu tư sinh lời bền vững. Hỗ trợ vay ngân hàng 70%."; } else if (card.category === 'raovat') { return "THÔNG TIN SẢN PHẨM RAO VẶT CHI TIẾT:\n" + "• Sản phẩm: " + title + "\n" + "• Nguồn gốc / Đơn vị: " + (subtitle || 'Tây Ninh') + "\n" + "• Giá bán: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" + "• Khu vực: " + location + "\n\n" + "MÔ TẢ TÌNH TRẠNG:\n" + "- Hàng cá nhân sử dụng kỹ, còn rất mới và hoạt động trơn tru 100%.\n" + "- Ngoại hình đẹp, đầy đủ phụ kiện đi kèm theo máy/xe.\n" + "- Mua bán trực tiếp tại nhà riêng để kiểm tra thoải mái, bao test 7 ngày cho người mua yên tâm."; } else if (card.category === 'suachua') { return "THÔNG TIN DỊCH VỤ SỬA CHỮA TẬN NƠI:\n" + "• Hạng mục: " + title + "\n" + "• Cơ sở phục vụ: " + (subtitle || 'Dịch vụ Tây Ninh 24/7') + "\n" + "• Chi phí: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" + "• Khu vực phục vụ: " + location + "\n\n" + "CAM KẾT DỊCH VỤ:\n" + "- Đội ngũ kỹ thuật viên lành nghề, nhiều năm kinh nghiệm, phục vụ chu đáo.\n" + "- Có mặt tận nơi sau 15 - 30 phút liên hệ, phục vụ tất cả các ngày trong tuần.\n" + "- Báo giá rõ ràng trước khi sửa chữa, linh kiện thay thế chính hãng có tem bảo hành."; } else { return "THÔNG TIN ẨM THỰC & KHÁCH SẠN:\n" + "• Địa điểm: " + title + "\n" + "• Đơn vị: " + (subtitle || 'Ẩm thực Tây Ninh') + "\n" + "• Mức giá: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" + "• Địa chỉ: " + location + "\n\n" + "GIỚI THIỆU KHÔNG GIAN:\n" + "- Thực đơn phong phú các món ăn đặc sản Tây Ninh chế biến đậm đà, tươi ngon.\n" + "- Không gian thoáng mát, sạch sẽ, bãi đỗ xe ô tô và xe máy rộng rãi, an ninh.\n" + "- Nhận phục vụ tiệc họp mặt gia đình, sinh nhật, liên hoan theo yêu cầu."; } };
const fillTemplateDescription = () => { const cat = postForm.value.category; if (cat === 'tuyendung') { postForm.value.description = "MÔ TẢ CÔNG VIỆC:\n- Thực hiện công tác tư vấn, bán hàng hoặc vận hành theo phân công.\n- Chăm sóc khách hàng và phối hợp tốt với đội nhóm.\n\nYÊU CẦU:\n- Độ tuổi từ 18 - 45, chăm chỉ, thật thà, có tinh thần trách nhiệm.\n- Ưu tiên ứng viên tại địa phương Tây Ninh.\n\nQUYỀN LỢI:\n- Lương cơ bản + thưởng năng suất + phụ cấp.\n- Hưởng đầy đủ chế độ bảo hiểm theo quy định pháp luật."; } else if (cat === 'batdongsan') { postForm.value.description = "THÔNG TIN CHI TIẾT BẤT ĐỘNG SẢN:\n- Diện tích: 100m² - 200m² (thổ cư 100%).\n- Pháp lý: Sổ hồng riêng chính chủ, sẵn sàng công chứng sang tên ngay.\n- Tiện ích: Đường ô tô vào tận nơi, gần chợ, trường học, dân cư đông đúc.\n- Thích hợp xây dựng nhà ở định cư hoặc đầu tư thanh khoản cao."; } else if (cat === 'raovat') { postForm.value.description = "CHI TIẾT MẶT HÀNG:\n- Tình trạng: Máy đẹp 98-99%, nguyên zin chưa qua sửa chữa.\n- Phụ kiện: Đầy đủ phụ kiện theo máy, dùng rất ổn định.\n- Xem và kiểm tra trực tiếp tại Tây Ninh, có bớt lộc cho khách nhanh nhẹn."; } else if (cat === 'suachua') { postForm.value.description = "CHI TIẾT DỊCH VỤ SỬA CHỮA:\n- Nhận bảo trì, lắp đặt và sửa chữa tận nhà nhanh chóng.\n- Thợ tay nghề cao, kiểm tra và báo giá công khai trước khi làm.\n- Có mặt sau 20 phút gọi trên khắp địa bàn Tây Ninh, bảo hành dài hạn."; } else { postForm.value.description = "GIỚI THIỆU ẨM THỰC / DỊCH VỤ:\n- Phục vụ các món ăn đặc sản Tây Ninh tươi ngon, chuẩn vị.\n- Không gian rộng rãi, thoáng mát, view đẹp, phục vụ tận tình.\n- Đặt bàn trước để nhận thêm nhiều ưu đãi hấp dẫn."; } showToast('Đã chèn mẫu mô tả gợi ý chuẩn theo chuyên mục!', 'info'); };
const selectPresetImage = () => { const presets = { 'tuyendung': 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80', 'batdongsan': 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=800&q=80', 'raovat': 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=800&q=80', 'suachua': 'https://images.unsplash.com/photo-1581578731548-c64695cc6952?auto=format&fit=crop&w=800&q=80', 'amthuc': 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80' }; postForm.value.previewUrl = presets[postForm.value.category] || presets['tuyendung']; showToast('Đã chọn ảnh minh họa sắc nét chuẩn theo chuyên mục!', 'success'); };
const onPostCategoryChange = () => { if (postForm.value.category === 'tuyendung') { postForm.value.badge = 'Tuyển gấp'; } else if (postForm.value.category === 'batdongsan') { postForm.value.badge = 'Chính chủ'; } else if (postForm.value.category === 'raovat') { postForm.value.badge = 'Giá tốt'; } else if (postForm.value.category === 'suachua') { postForm.value.badge = 'Uy tín 24/7'; } else { postForm.value.badge = 'Đặc sản'; } };
const shareCard = (card) => { if (navigator.clipboard) { navigator.clipboard.writeText(window.location.href); } showToast('Đã sao chép liên kết bài đăng!', 'success'); };
const openApplyModal = (card) => { selectedItem.value = card; showApplyModal.value = true; };
const openContactModal = (card) => { selectedItem.value = card; showContactModal.value = true; };
const openCallModal = (card) => { showPopup('Gọi Điện Nhanh', 'Gọi trực tiếp cho ' + card.title + ' qua Hotline/Zalo: ' + (card.phone || '0908.123.456'), 'info'); };
const postImageDriveStatus = ref(''); const modalNewCommentText = ref('');
const incrementView = (card) => { if (!card) return; card.viewsCount = (card.viewsCount || 0) + 1; };
const toggleLike = (card) => { if (!card) return; if (card.likedByMe) { card.likedByMe = false; card.likesCount = Math.max(0, (card.likesCount || 1) - 1); showToast('Đã bỏ thích bài đăng', 'info'); } else { card.likedByMe = true; card.likesCount = (card.likesCount || 0) + 1; showToast('Đã thích bài đăng!', 'success'); } };
